/****************************************************************************
 * Manual KICKPI-K7 SKW6621S SDIO probe hooks.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <syslog.h>

#include <nuttx/sdio.h>

#include "rk3576_dwmmc.h"
#include "skw6621s/skw6621s_sdio.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int kickpi_k7_bt_probe(void)
{
  struct skw6621s_probe_s result;
  FAR struct sdio_dev_s *sdio;
  int ret;

  ret = rk3576_dwmmc_probe(RK3576_DWMMC_SDIO_BASE);
  if (ret < 0)
    {
      syslog(LOG_ERR, "SKW6621S: RK3576 SDIO host probe failed: %d\n", ret);
      return ret;
    }

  sdio = rk3576_dwmmc_initialize(RK3576_DWMMC_SDIO_BASE);
  if (sdio == NULL)
    {
      return -ENODEV;
    }

  return skw6621s_sdio_probe(sdio, &result);
}

int kickpi_k7_bt_initialize(void)
{
  /* HCI must not register before firmware boot and RX framing exist. */

  syslog(LOG_WARNING,
         "SKW6621S: firmware/HCI initialization is not implemented yet\n");
  return -ENOSYS;
}

#include <arch/board/board.h>

int main(int argc, char *argv[])
{
  int ret;

  if (argc >= 2 && strcmp(argv[1], "init") == 0)
    {
      ret = kickpi_k7_bt_initialize();
      printf("ret=%d\n", ret);
      return ret < 0 ? 1 : 0;
    }

  if (argc < 2 || strcmp(argv[1], "probe") == 0)
    {
      ret = kickpi_k7_bt_probe();
      printf("ret=%d\n", ret);
      return ret < 0 ? 1 : 0;
    }

  printf("用法: bt probe|init\n");
  return 1;
}
static int skw_read_identity(FAR struct sdio_dev_s *sdio,
                             FAR uint8_t identity[16])
{
  int ret;
  int i;

  /* The four CMD52 writes form one address-latch operation. Probe has only
   * one caller; the runtime driver must protect this sequence with its bus
   * mutex before concurrent TX/RX is enabled.
   */

  for (i = 0; i < 4; i++)
    {
      ret = skw_write_f0(sdio, SKW_ADDR_LATCH + i,
                         (SKW_CHIP_ID_ADDRESS >> (8 * i)) & 0xff);
      if (ret < 0)
        {
          return ret;
        }
    }

  /* The SDK reads this window with sdio_memcpy_fromio (incrementing CMD53).
   * Fixed-address transfers are used for the separate packet FIFO at 0x20.
   */

  return sdio_io_rw_extended(sdio, false, SKW_FUNCTION,
                             SKW_DIRECT_WINDOW, true, identity, 16, 0);
}

