    }
    else if(pkt_type == HCI_ACLDATA_PKT)
    {
        hdev->stat.acl_tx++;
        skb_queue_tail(&data->data_txq, skb);
    }
    else if(pkt_type == HCI_SCODATA_PKT)
    {
        skb_queue_tail(&data->audio_txq, skb);
        hdev->stat.sco_tx++;
    }
    else
