295	/* skw_sdio2_sdma_parser + the LOOPCHECK branch of skw_sdio2_handle_packet.
296	 * Returns 1 when the version string arrived.
297	 */
298	
299	static int skw_parse(FAR struct sdio_dev_s *sdio, FAR uint8_t *buf,
300	                     unsigned int npac)
301	{
302	  unsigned int i;
303	  int done = 0;
304	
305	  for (i = 0; i < npac; i++)
306	    {
307	      FAR uint8_t *p = buf + i * SKW_PAC_SIZE;
308	      uint32_t hdr = skw_le32(p);
309	      unsigned int len = hdr & 0xffff;
310	      unsigned int ch = hdr >> 24;
311	      char cmd[64];
312	      size_t n;
313	
314	      if ((hdr >> 23) & 1)
315	        {
316	          break;
317	        }
318	
319	      if (len == 0 || len > SKW_PAC_SIZE - 4)
320	        {
321	          syslog(LOG_WARNING, "SKW6621S: rx bad header 0x%08" PRIx32 "\n",
322	                 hdr);
323	          break;
324	        }
325	
326	      if (ch != SKW_LOOPCHECK_CH || len < 12)
327	        {
328	          syslog(LOG_INFO, "SKW6621S: rx ch %u len %u\n", ch, len);
329	          continue;
330	        }
331	
332	      /* Payload string starts at +16 and is len - 12 bytes long */
333	
334	      n = len - 12 < sizeof(cmd) - 1 ? len - 12 : sizeof(cmd) - 1;
335	      memcpy(cmd, p + 16, n);
336	      cmd[n] = '\0';
337	      syslog(LOG_INFO, "SKW6621S: LOOPCHECK \"%s\"\n", cmd);
338	
339	      if (strncmp(cmd, "BSPREADY", 8) == 0)
340	        {
341	          int ret = skw_send(sdio, SKW_LOOPCHECK_CH, "RDVERSION", 9);
342	          syslog(LOG_INFO, "SKW6621S: sent RDVERSION: %d\n", ret);
343	        }
344	      else if (strncmp(cmd, "trunk_W", 7) == 0)
345	        {
346	          done = 1;
347	        }
348	      else if (strncmp(cmd, "BSPASSERT", 9) == 0)
349	        {
350	          return -EIO;
351	        }
352	    }
353	
354	  return done;
355	}
